const READING_TOPICS=[
 {id:'plotting',name:'Plotting & visualization',tip:'Label axes and units, check the data lengths, and interpret the shape of the plot.'},
 {id:'testing',name:'Testing & validation',tip:'Use independent expected answers, boundary cases, and explicit rules for invalid inputs.'},
 {id:'data',name:'Files & data processing',tip:'Keep source measurements separate from derived results. State the schema, units, and missing-data policy.'},
 {id:'algorithms',name:'Search, sorting & algorithms',tip:'Check algorithm assumptions before comparing results or the amount of work.'},
 {id:'matrices',name:'Matrices & linear systems',tip:'Check dimensions and units. Substitute a computed solution back into the original equations.'},
 {id:'numerical',name:'Roots & numerical methods',tip:'State the interval, tolerance, stopping rule, and meaning of any reported error.'},
 {id:'simulation',name:'Simulation & sampling',tip:'Separate the model assumptions, numerical step size, and sampling variability.'},
 {id:'objects',name:'Objects & inheritance',tip:'Track each instance’s state and keep queries, updates, and validation responsibilities clear.'}
];
let readingBook='all',readingChapter='all',readingSearch='',readingPage=0,programPage=0;
const PAGE_SIZE=24;
function readingCases(){const term=readingSearch.toLowerCase().trim();return READING_EXAMPLES.filter(p=>(readingBook==='all'||p.reading===readingBook)&&(readingChapter==='all'||String(p.chapter)===readingChapter)&&(!term||[p.name,p.chapterTitle,p.source,p.code,p.explanation,p.topic].join(' ').toLowerCase().includes(term)));}
function readingChapterOptions(){if(readingBook==='all')return '<option value="all">Choose a reading first</option>';const book=COURSE_READINGS.find(b=>b.id===readingBook);return '<option value="all">All chapters</option>'+Object.entries(book.chapters).map(([n,title])=>`<option value="${n}" ${readingChapter===n?'selected':''}>${n}. ${esc(title)}</option>`).join('');}
function pageControls(page,total,scope){const pages=Math.max(1,Math.ceil(total/PAGE_SIZE));return `<div class="pagination"><button class="secondary" data-${scope}-page="${page-1}" ${page===0?'disabled':''}>← Previous</button><span>Page ${page+1} of ${pages} · ${total} examples</span><button class="secondary" data-${scope}-page="${page+1}" ${page+1>=pages?'disabled':''}>Next →</button></div>`;}
function renderReadings(){const list=readingCases();readingPage=Math.min(readingPage,Math.max(0,Math.ceil(list.length/PAGE_SIZE)-1));const visible=list.slice(readingPage*PAGE_SIZE,(readingPage+1)*PAGE_SIZE);document.getElementById('reading-grid').innerHTML=visible.length?visible.map(programCard).join(''):'<p class="empty">No examples match. Try another chapter or search term.</p>';const controls=pageControls(readingPage,list.length,'reading');document.getElementById('reading-pagination-top').innerHTML=controls;document.getElementById('reading-pagination-bottom').innerHTML=controls;document.getElementById('reading-count').textContent=`${list.length} examples`;}
function readingHome(){const done=READING_EXAMPLES.filter(p=>state.records[p.id]).length;paint(`<div class="intro"><span class="eyebrow">THE TWO SUGGESTED COURSE READINGS</span><h1>Read an idea. Explore it in code.</h1><p>${READING_EXAMPLES.length} additional standalone programs, with verified output, explanations, and a prompt to modify each example. Instructor: Prof. Yanwei Wang.</p></div><div class="bank-grid reading-books">${COURSE_READINGS.map(book=>`<section class="panel"><span class="tag">${esc(book.author)}</span><h2>${esc(book.title)}</h2><p class="muted">${esc(book.edition)}</p><p>${esc(book.summary)}</p><p class="code-info">${READING_EXAMPLES.filter(p=>p.reading===book.id).length} examples in this collection</p><button class="secondary" data-reading-book="${book.id}">Browse these examples →</button></section>`).join('')}</div><section class="collection-banner"><div><h2>${done} / ${READING_EXAMPLES.length} examples attempted this session</h2><p>Run a complete example, predict its result, then change one input and explain what happens.</p></div><a class="secondary download-link" href="downloads/eng101-reading-examples.zip" download>Download all ${READING_EXAMPLES.length} programs ↓</a></section><div class="filter-bar" aria-label="Choose a reading">${[['all','Both readings'],['wang','Wang course manuscript'],['guttag','Guttag companions']].map(([id,label])=>`<button class="chip ${readingBook===id?'active':''}" data-reading-book="${id}" aria-pressed="${readingBook===id}">${label}</button>`).join('')}</div><div class="program-toolbar"><label class="search"><input id="reading-search" type="search" value="${esc(readingSearch)}" placeholder="Find a concept, function, or example…" aria-label="Search reading examples"></label><label class="topic-select">Chapter <select id="reading-chapter" ${readingBook==='all'?'disabled':''}>${readingChapterOptions()}</select></label><button class="text-button" id="clear-reading-filters">Clear filters</button><span class="muted" id="reading-count" role="status"></span></div><div id="reading-pagination-top"></div><div class="program-grid" id="reading-grid"></div><div id="reading-pagination-bottom"></div><section class="panel reading-note" aria-labelledby="reading-overview-title">
<h2 id="reading-overview-title">About these examples</h2>
<p>Explore ${READING_EXAMPLES.length} complete Python programs, from variables, loops and functions to data analysis, visualization, numerical methods and simulation. The examples connect programming ideas with engineering calculations and practical problem solving.</p>
<p>Each example includes code, reference output, an explanation and a small change to try. Predict the output, run the program, then modify an input or method and explain the result. Examples that use NumPy, pandas, Matplotlib or SciPy list the required packages.</p>
</section>
<section class="panel reading-note" aria-labelledby="reading-references-title">
<h2 id="reading-references-title">References and useful resources</h2>
<h3>Books and course notes</h3>
<ol>
<li>Yanwei Wang. <em>Programming for Engineers with Python.</em> Course manuscript.</li>
<li>John V. Guttag. <a href="https://mitpress.mit.edu/9780262529624/introduction-to-computation-and-programming-using-python/" target="_blank" rel="noopener noreferrer"><em>Introduction to Computation and Programming Using Python: With Application to Understanding Data.</em></a> Second edition. MIT Press, 2016.</li>
</ol>
<h3>Online learning and documentation</h3>
<ul>
<li><a href="https://docs.python.org/3/tutorial/" target="_blank" rel="noopener noreferrer">The Python Tutorial</a> and <a href="https://docs.python.org/3/library/" target="_blank" rel="noopener noreferrer">Python standard library reference</a> — language features, built-in types and modules.</li>
<li><a href="https://ocw.mit.edu/courses/6-0001-introduction-to-computer-science-and-programming-in-python-fall-2016/" target="_blank" rel="noopener noreferrer">MIT OpenCourseWare: Introduction to Computer Science and Programming in Python</a> — lecture videos, slides, code and practice problems.</li>
<li><a href="https://numpy.org/doc/stable/user/absolute_beginners.html" target="_blank" rel="noopener noreferrer">NumPy beginner’s guide</a> — arrays and numerical calculations.</li>
<li><a href="https://pandas.pydata.org/docs/getting_started/index.html" target="_blank" rel="noopener noreferrer">pandas getting started</a> — reading, exploring and processing tabular data.</li>
<li><a href="https://matplotlib.org/stable/users/explain/quick_start.html" target="_blank" rel="noopener noreferrer">Matplotlib quick start guide</a> — creating and labeling plots.</li>
<li><a href="https://docs.scipy.org/doc/scipy/tutorial/index.html" target="_blank" rel="noopener noreferrer">SciPy user guide</a> — numerical methods, optimization and statistics.</li>
</ul>
</section>`,'readings');renderReadings();}
function referenceExtras(p){
 if(!p.reading&&!p.explanation)return '';
 return `<section class="reading-explanation"><h3>Why it works</h3><p>${esc(p.explanation)}</p>${p.images?.length?`<div class="reference-figures">${p.images.map((src,i)=>`<figure><img src="${esc(src)}" alt="${esc(p.name)} — reference plot ${i+1}" loading="lazy"><figcaption>Reference plot ${i+1} · ${esc(p.source)}</figcaption></figure>`).join('')}</div>`:''}<h3>Change it and predict again</h3><p>${esc(p.tryIt)}</p>${p.tests?`<details class="hint"><summary>Regression checks to run after the program</summary><p>Append these assertions to the complete program and run them in Python. Add your own independent boundary and invalid-input checks.</p><pre><code>${esc(p.tests)}</code></pre></details>`:''}</section>`;
}

async function copyProgram(id){const p=PROGRAMS.find(p=>p.id===id);const status=document.getElementById('copy-status');try{await navigator.clipboard.writeText(p.code);status.textContent='Program copied.';}catch{status.textContent='Copy is unavailable in this browser. Select the code text and copy it.';}}
function downloadProgram(id){const p=PROGRAMS.find(p=>p.id===id);const file=new Blob([p.code+'\n'],{type:'text/x-python;charset=utf-8'});const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=p.id+'.py';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.readingBook){readingBook=b.dataset.readingBook;readingChapter='all';readingPage=0;readingHome();}else if(b.dataset.readingPage!==undefined&&!b.disabled){readingPage=Number(b.dataset.readingPage);renderReadings();window.scrollTo({top:document.getElementById('reading-pagination-top').getBoundingClientRect().top+window.scrollY-20,behavior:'smooth'});}else if(b.dataset.programPage!==undefined&&!b.disabled){programPage=Number(b.dataset.programPage);renderProgramList();}else if(b.id==='clear-reading-filters'){readingBook=readingChapter='all';readingSearch='';readingPage=0;readingHome();}else if(b.id==='copy-program')copyProgram(b.dataset.id);else if(b.id==='download-program')downloadProgram(b.dataset.id);});
document.addEventListener('input',event=>{if(event.target.id==='reading-search'){readingSearch=event.target.value;readingPage=0;renderReadings();}});
document.addEventListener('change',event=>{if(event.target.id==='reading-chapter'){readingChapter=event.target.value;readingPage=0;renderReadings();}});
